std::uint32_t CurrentThreadId() noexcept;
void Backtrace(std::vector<std::string>& stack, std::size_t size, std::size_t skip = 0) noexcept;
std::string Backtrace(std::size_t size, std::size_t skip = 0, std::string_view prefix = "") noexcept;

template <typename T, typename... Args>
class Singleton {
public:
    static T& Instance() {
        static T instance(std::forward<Args>(args)...);
        return instance;
    }
};

template <typename T, typename... Args>
class SingletonPtr {
public:
    using Ptr = std::unique_ptr<T>;

    static Ptr& Instance() {
        static Ptr instance(std::make_unique<T>(std::forward<Args>(args)...));
        return instance;
    }
};

template <typename T, typename Cleaner>
class RAII {
public:
    RAII(T obj, Cleaner cleaner) : obj_(obj), cleaner_(cleaner) {}

    ~RAII() { cleaner_(obj_); }

    RAII(const RAII&) = delete;
    RAII(RAII&&) = delete;
    RAII& operator=(const RAII&) = delete;
    RAII& operator=(RAII&&) = delete;

private:
    T obj_;
    Cleaner cleaner_;
};

class MappedReadOnlyFile {
public:
    MappedReadOnlyFile() = default;

    MappedReadOnlyFile(const MappedReadOnlyFile&) = delete;
    MappedReadOnlyFile& operator=(const MappedReadOnlyFile&) = delete;

    MappedReadOnlyFile(MappedReadOnlyFile&& other) noexcept : data_(other.data_), size_(other.size_), path_(std::move(other.path_)) {
        other.data_ = nullptr;
        other.size_ = 0;
    }

    MappedReadOnlyFile& operator=(MappedReadOnlyFile&& other) noexcept {
        if (this != &other) {
            Unmap();
            data_ = other.data_;
            size_ = other.size_;
            path_ = std::move(other.path_);
            other.data_ = nullptr;
            other.size_ = 0;
        }
        return *this;
    }

    ~MappedReadOnlyFile() { Unmap(); }

    void Map(std::string path);
    void Unmap();
    std::size_t Size() const noexcept { return size_; }
    const char* Data() const noexcept { return data_; }
    const std::string& Path() const noexcept { return path_; }

private:
    void Check(const std::string& path);

    const char* data_ = nullptr;
    std::size_t size_ = 0;
    std::string path_;
};

template <typename T, typename U, typename Ret = T>
concept Addable = requires(T t, U u) {
    { t + u } -> std::convertible_to<Ret>;
};

}

#endif // UTIL_H

#include "util.h"
#include <execinfo.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/syscall.h>
#include <unistd.h>
#include <algorithm>
#include <cassert>
#include <cerrno>
#include <iterator>
#include <sstream>
#include <system_error>

namespace ws {

std::string StringToLower(std::string str) noexcept {
    std::ranges::transform(str, str.begin(), ::tolower);
    return str;
}

std::string StringToUpper(std::string str) noexcept {
    std::ranges::transform(str, str.begin(), ::toupper);
    return str;
}

std::string ReplaceAllSubstring(std::string_view str, std::string_view from, std::string_view to) noexcept {
    std::ostringstream oss;
    std::size_t pos = 0;
    while (pos < str.length()) {
        auto next_pos = str.find(from, pos);
        if (next_pos == std::string_view::npos) {
            oss << str.substr(pos);
            break;
        }
        oss << str.substr(pos, next_pos - pos) << to;
        pos = next_pos + from.length();
    }
    return oss.str();
}

std::vector<std::string> SplitString(const std::string& str, const std::regex& pattern) noexcept {
    std::sregex_token_iterator iter(str.begin(), str.end(), pattern, -1);
    std::sregex_token_iterator end;
    return {iter, end};
}

std::vector<std::string> SplitStringToLines(const std::string& str) noexcept {
    static const std::regex newline_regex("\r?\n");
    return SplitString(str, newline_regex);
}

YAML::Node LoadYamlString(std::string_view str, std::initializer_list<std::string_view> required_fields) {
    YAML::Node node = YAML::Load(std::string(str));
    for (auto field : required_fields) {
        if (!node[field]) {
            throw std::invalid_argument(fmt::format("Required field '{}' is missing", field));
        }
    }
    return node;
}

void ThrowIfYamlFieldIsNotScalar(const YAML::Node& node, std::string_view field) {
    if (!node[field] || !node[field].IsScalar()) {
        throw std::invalid_argument(fmt::format("Field '{}' is not a scalar", field));
    }
}

constexpr bool IsValidFileDescriptor(FileDescriptor fd) noexcept {
    return fd >= 0;
}

void SetFileDescriptorAsNonblocking(FileDescriptor fd) {
    int flags = fcntl(fd, F_GETFL);
    if (flags == -1 || fcntl(fd, F_SETFL, flags | O_NONBLOCK) == -1) {
        throw std::system_error(errno, std::generic_category());
    }
}

[[noreturn]] void ThrowLastSystemError() {
    throw std::system_error(errno, std::generic_category());
}

std::uint32_t CurrentThreadId() noexcept {
    return static_cast<std::uint32_t>(syscall(SYS_gettid));
}

void Backtrace(std::vector<std::string>& stack, std::size_t size, std::size_t skip) noexcept {
    void* buffer[size];
    int nptrs = backtrace(buffer, size);
    char** strings = backtrace_symbols(buffer, nptrs);
    if (strings == nullptr) {
        return;
    }
    for (int i = skip; i < nptrs; ++i) {
        stack.push_back(strings[i]);
    }
    free(strings);
}

std::string Backtrace(std::size_t size, std::size_t skip, std::string_view prefix) noexcept {
    std::vector<std::string> stack;
    Backtrace(stack, size, skip);
    std::ostringstream oss;
    for (const auto& frame : stack) {
        oss << prefix << frame << "\n";
    }
    return oss.str();
}

void MappedReadOnlyFile::Map(std::string path) {
    Check(path);
    int fd = open(path.c_str(), O_RDONLY);
    if (fd == -1) {
        throw std::system_error(errno, std::generic_category());
    }
    struct stat sb;
    if (fstat(fd, &sb) == -1) {
        close(fd);
        throw std::system_error(errno, std::generic_category());
    }
    data_ = static_cast<const char*>(mmap(nullptr, sb.st_size, PROT_READ, MAP_PRIVATE, fd, 0));
    if (data_ == MAP_FAILED) {
        close(fd);
        throw std::system_error(errno, std::generic_category());
    }
    size_ = sb.st_size;
    path_ = std::move(path);
    close(fd);
}

void MappedReadOnlyFile::Unmap() {
    if (data_) {
        munmap(const_cast<char*>(data_), size_);
        data_ = nullptr;
        size_ = 0;
        path_.clear();
    }
}

void MappedReadOnlyFile::Check(const std::string& path) {
    struct stat sb;
    if (stat(path.c_str(), &sb) == -1) {
        throw std::system_error(errno, std::generic_category());
    }
    if (S_ISDIR(sb.st_mode)) {
        throw std::invalid_argument(fmt::format("Path '{}' refers to a directory", path));
    }
}

}
